# -*- coding: utf-8 -*-
# =============================================================================
# @file:  alembic/versions/0003_identity_columns.py
# @brief: Alembic migration 0003: converts seven BIGSERIAL id columns to IDENTITY on PostgreSQL.
# @notes: Alembic revision kept as migration history. Do not edit it; schema
#         changes must go into a new revision.
# =============================================================================

"""
0003_identity_columns — convert seven `BIGSERIAL` ids to `IDENTITY` on PostgreSQL (phase E.4.2).

Why?
----
`0001` deliberately created `BIGSERIAL` (sequence + `nextval` as the default) to reproduce the
"today's shape" of SQLite. On PostgreSQL, the standard and recommended shape of a modern schema is
`GENERATED BY DEFAULT AS IDENTITY`: the sequence is not a separate object that someone could tamper
with by mistake, its ownership and lifetime are tied to the column, and `pg_dump`/restore is cleaner.
The "auto-increment" behaviour is in practice the same.

Seven tables (the same seven tables that have `AUTOINCREMENT` in SQLite):

    logs · toner_history · sensor_readings · users · security_events ·
    yield_samples · toner_snapshots_v2

On SQLite this migration is a **no-op**
--------------------------------------
`INTEGER PRIMARY KEY AUTOINCREMENT` is the only SQLite mechanism for an id with the same meaning as
IDENTITY, and today's schema of the program is exactly that. This migration only checks that each of
the seven tables has it; if a table does not, the run stops with a clear message (a mismatched schema,
not a silent skip).

Four steps on PG (each of the three findings was measured, not guessed)
-----------------------------------------------------------------------
1) `ADD GENERATED BY DEFAULT AS IDENTITY` is rejected when the column has `DEFAULT nextval(...)`:

       ERROR: column "id" of relation "…" already has a default value

   So first `DROP DEFAULT`.
2) The old sequence (`<table>_id_seq`) was owned by the column; `DROP DEFAULT` does not remove the
   ownership, but the sequence stays **unused**. It is dropped, otherwise it remains as leftover
   schema (and it causes confusion in `information_schema.sequences`).
3) `ADD GENERATED BY DEFAULT AS IDENTITY` creates a **new** sequence that starts at 1 — on a table
   with data that means a key conflict on the next insert. Measured: on a table with ids 1..3 (no key)
   it produced duplicate values. So `ALTER COLUMN id RESTART WITH <max(id)+1>` runs right away
   (an empty table ⇒ 1).

`BY DEFAULT` (not `ALWAYS`) was chosen so that an explicit insert of `id` is still possible: the
`import_db` path (and any data-migration tool) passes ids explicitly, and `ALWAYS` would break them.

Safety
------
• **Idempotent:** a column that is already `is_identity = 'YES'` is skipped;
• `RESTART WITH` is still set again (harmless and useful: if data was inserted explicitly after the
  previous run, the value is corrected);
• **Rollback path:** `downgrade` goes back to `BIGSERIAL`: `DROP IDENTITY` ⇒ create a sequence with
  the same historical name ⇒ `SET DEFAULT nextval(...)` ⇒ `OWNED BY` ⇒ `setval` on `max(id)`.
"""
from __future__ import annotations

import logging

import sqlalchemy as sa
from alembic import op

revision = "0003"
down_revision = "0002"
branch_labels = None
depends_on = None

log = logging.getLogger("alembic.runtime.migration")

#: Tables whose id must become IDENTITY (the same seven AUTOINCREMENT tables as in SQLite).
IDENTITY_TABLES = (
    "logs",
    "toner_history",
    "sensor_readings",
    "users",
    "security_events",
    "yield_samples",
    "toner_snapshots_v2",
)


def _is_postgres() -> bool:
    """Return True when the migration runs against PostgreSQL."""
    return op.get_bind().dialect.name == "postgresql"


def _identity_state(conn, table: str):
    """``(is_identity, column_default)`` of the id column from ``information_schema``."""
    row = conn.execute(
        sa.text(
            "SELECT is_identity, column_default FROM information_schema.columns "
            "WHERE table_schema = current_schema() "
            "AND table_name = :t AND column_name = 'id'"
        ),
        {"t": table},
    ).fetchone()
    return (None, None) if row is None else (row[0], row[1])


def _max_id(conn, table: str):
    """Return the current maximum id of a table (None for an empty table)."""
    return conn.execute(sa.text(f'SELECT max(id) FROM "{table}"')).fetchone()[0]


def _sqlite_has_autoincrement(conn, table: str) -> bool:
    """Return True when the table's SQLite DDL declares AUTOINCREMENT."""
    row = conn.execute(
        sa.text("SELECT sql FROM sqlite_master WHERE type='table' AND name = :t"),
        {"t": table},
    ).fetchone()
    if row is None or row[0] is None:
        return False
    return "AUTOINCREMENT" in str(row[0]).upper()


def upgrade() -> None:
    """Convert the id columns to IDENTITY on PostgreSQL; verify AUTOINCREMENT on SQLite."""
    conn = op.get_bind()

    if not _is_postgres():
        missing = [t for t in IDENTITY_TABLES if not _sqlite_has_autoincrement(conn, t)]
        if missing:
            raise RuntimeError(
                "0003_identity_columns: این جدول‌ها در SQLite «AUTOINCREMENT» ندارند: "
                + ", ".join(missing) +
                " — schema با انتظار این migration هم‌خوان نیست (کار E.4.2)."
            )
        log.info(
            "0003_identity_columns: SQLite ⇒ no-op (INTEGER PRIMARY KEY AUTOINCREMENT "
            "هم‌معنای IDENTITY است). %d جدول بررسی و تأیید شد.", len(IDENTITY_TABLES)
        )
        return

    for table in IDENTITY_TABLES:
        is_identity, default = _identity_state(conn, table)
        if is_identity is None:
            raise RuntimeError(
                f"0003_identity_columns: ستون id جدول «{table}» در دیتابیس نیست."
            )

        seq_name = f"{table}_id_seq"
        if is_identity == "YES":
            if default is None:
                # Healthy expected state: the internal IDENTITY sequence is not visible in column_default.
                log.info("0003_identity_columns: %s.id از قبل IDENTITY است ⇒ رد شد.", table)
            else:
                log.info("0003_identity_columns: %s.id IDENTITY است (default=%s) ⇒ رد شد.",
                         table, default)
        else:
            # Step 1: the old default (nextval) must go, otherwise ADD IDENTITY is rejected.
            op.execute(f'ALTER TABLE "{table}" ALTER COLUMN id DROP DEFAULT')
            # Step 2: the old sequence is unused; it is dropped (if it exists).
            op.execute(f'DROP SEQUENCE IF EXISTS "{seq_name}"')
            # Step 3: the new IDENTITY sequence.
            op.execute(
                f'ALTER TABLE "{table}" ALTER COLUMN id '
                f"ADD GENERATED BY DEFAULT AS IDENTITY"
            )
            log.info("0003_identity_columns: %s.id ⇒ IDENTITY (BY DEFAULT)", table)

        # Step 4 (always): align the sequence with the existing data.
        max_id = _max_id(conn, table)
        restart = 1 if max_id is None else int(max_id) + 1
        op.execute(f'ALTER TABLE "{table}" ALTER COLUMN id RESTART WITH {restart}')
        log.info("0003_identity_columns: %s.id ⇒ RESTART WITH %d (max_id=%s)",
                 table, restart, max_id)


def downgrade() -> None:
    """Convert the id columns back to BIGSERIAL on PostgreSQL; no-op on SQLite."""
    conn = op.get_bind()

    if not _is_postgres():
        log.info("0003_identity_columns (downgrade): SQLite ⇒ no-op.")
        return

    for table in IDENTITY_TABLES:
        is_identity, _default = _identity_state(conn, table)
        if is_identity is None:
            raise RuntimeError(
                f"0003_identity_columns (downgrade): ستون id جدول «{table}» نیست."
            )
        if is_identity != "YES":
            log.info("0003_identity_columns (downgrade): %s.id از قبل IDENTITY نیست ⇒ رد شد.",
                     table)
        else:
            op.execute(f'ALTER TABLE "{table}" ALTER COLUMN id DROP IDENTITY')

        seq_name = f"{table}_id_seq"
        op.execute(f'CREATE SEQUENCE IF NOT EXISTS "{seq_name}"')
        op.execute(
            f'ALTER TABLE "{table}" ALTER COLUMN id SET DEFAULT nextval(\'{seq_name}\')'
        )
        op.execute(f'ALTER SEQUENCE "{seq_name}" OWNED BY "{table}".id')

        max_id = _max_id(conn, table)
        if max_id is None:
            op.execute(f"SELECT setval('{seq_name}', 1, false)")
        else:
            op.execute(f"SELECT setval('{seq_name}', {int(max_id)}, true)")
        log.info("0003_identity_columns (downgrade): %s.id ⇒ BIGSERIAL (seq=%s, max_id=%s)",
                 table, seq_name, max_id)
